# -*- coding: utf-8 -*-
"""手机端界面文件（打进 APK；运行时解压到应用私有目录）。

Chaquopy 会把 python 目录打成 .imy（本质是 zip），Python 里没法直接 open() 读，
所以把前端三个文件 base64 塞进这里，start() 时解出来给 http.server 用。
"""
import base64
import os

FILES = {
    'm.html': '',
    'm.css': '',
    'm.js': '',
    'manifest.webmanifest': '',
    'sw.js': '',
    'icon-192.png': '',
    'icon-512.png': '',
}


def extract(dirpath: str) -> str:
    """把界面文件写出来，返回目录。已存在且大小相同就跳过。"""
    os.makedirs(dirpath, exist_ok=True)
    for name, b64 in FILES.items():
        p = os.path.join(dirpath, name)
        raw = base64.b64decode(b64)
        try:
            if os.path.getsize(p) == len(raw):
                continue
        except OSError:
            pass
        with open(p, "wb") as f:
            f.write(raw)
    return dirpath
